import{_ as t,o,c as e,ag as u}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第87章 谁先发的","description":"","frontmatter":{},"headers":[],"relativePath":"第87章_谁先发的.md","filePath":"第87章_谁先发的.md"}'),a={name:"第87章_谁先发的.md"};function _(q,p,r,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[u('<h1 id="第87章-谁先发的" tabindex="-1">第87章 谁先发的 <a class="header-anchor" href="#第87章-谁先发的" aria-label="Permalink to &quot;第87章 谁先发的&quot;">​</a></h1><p>到大四上学期，我们开始数谁先发的消息。</p><p>这件事不是我起的头。</p><p>是她。</p><p>十月有一天，她发了一句。</p><p>她说，我想问你一件事。</p><p>我说，你说。</p><p>她说，这个月你发我的比我发你的多。</p><p>我说，我没数。</p><p>她说，我数了。</p><p>我说，你数这个干什么。</p><p>她说，因为我想知道你累不累。</p><p>我说，我不累。</p><p>她说，你要是累，你说一句，我这周多打一点。</p><p>我说，你多打一点你会画不完图。</p><p>她说，那你说啊。</p><p>我说，我不累。</p><p>她说，你看，这就是我不爱问你这个的原因。</p><p>她说，你讲&quot;不累&quot;，我要是不信，我就是不体谅你。</p><p>她说，我要是信了，我下周还是发三条，你就还是发三十条。</p><p>我说，那你希望我怎么办。</p><p>她说，我希望你自己发现。</p><p>她说，你发现你在这个对话里发得太多，你自己就会少发一点。</p><p>她说，我要是替你指出来，你就变成在被管。</p><p>她说，我不想要一个被我管的。</p><p>我说，那你现在就是在管。</p><p>她说，对。</p><p>她说，我今天忍不住了。</p><p>她说，因为我昨天看见一个东西。</p><p>我说，什么。</p><p>她说，我这边一个朋友，她跟她对象也是这种，一个人发一百条，一个人回三条。</p><p>她说，她觉得那三条很珍贵。</p><p>她说，她说&quot;他今天回我三条，我这一周都高兴&quot;。</p><p>她说，我在旁边听，我浑身发冷。</p><p>我说，为什么。</p><p>她说，因为我听出来她那三条是我给你的量。</p><p>她说，我什么时候变成那个不给的人，我不知道。</p><p>她说，我今天告诉你这个，不是我要多回。</p><p>她说，我要你去少发。</p><p>我说，怎么少。</p><p>她说，你别每天早上发一句&quot;今天冷&quot;。</p><p>我说，那我不发。</p><p>她说，你也别说&quot;我今天在食堂听见那首歌&quot;。</p><p>我说，那我说什么。</p><p>她说，你等我有事的时候再说。</p><p>我说，那你没事的时候我就不说话。</p><p>她说，对。</p><p>她说，这样我们两个才是有来有回。</p><p>我说，我听懂了。</p><p>她说，你没听懂。</p><p>她说，你要是听懂了你现在会难受，你会忍一句客气话，你会说&quot;好，我改&quot;。</p><p>她说，你一说&quot;好，我改&quot;我心里就堵得慌。</p><p>我说，那我讲什么。</p><p>她说，你讲&quot;我不想改&quot;。</p><p>我坐在那儿。</p><p>我说，我不想改。</p><p>她说，你看，这不就出来了。</p><p>她说，你讲完这句，我今天这一晚上就轻松了。</p><p>她说，因为我知道你不是在配合我。</p><p>她说，配合这个东西，你配合我一次，你要还我十次。</p><p>她说，我不想当那个让你还的人。</p><p>那一场以后，我们把这件事变成了一个规矩。</p><p>谁先发不要紧，要紧的是不要连发三条没回音。</p><p>我们把这个叫&quot;三句线&quot;。</p><p>她定的。</p><p>她说，你要是连着发三条我没回，说明我今天不行了。</p><p>她说，你不要发第四条。</p><p>我说，第四条会怎样。</p><p>她说，第四条你就要开始问我为什么不回。</p><p>她说，你一问，我就要开始编。</p><p>她说，我编的东西我第二天要认。</p><p>她说，我认的时候我难受，你听见了你也难受。</p><p>她说，所以我们停在第三条。</p><p>我说，好。</p><p>那年冬天这个规矩用上了很多次。</p><p>有一次是十二月。</p><p>我发了三条。</p><p>第一条：今天下了今年第一场雪。</p><p>第二条：我们楼下那辆车被埋了一半。</p><p>第三条：你那边下雪吗。</p><p>我没发第四条。</p><p>我发完第三条以后，我把手机扣在桌上。</p><p>我坐在那儿，等。</p><p>她那边的下午四点，我这边夜里十二点。</p><p>十二点四十，没有。</p><p>一点，没有。</p><p>我躺下。</p><p>我一点四十没睡着，我又拿起来看了一眼。</p><p>没有。</p><p>第二天早上我七点四十拿手机。</p><p>一条。</p><p>她昨天下午五点十六看到的。</p><p>她那边四点十六是下课，她站在走廊上打的。</p><p>她回的是：我这里没有雪，我这里在漏水。</p><p>后面是一张图。</p><p>她那个宿舍的天花板，有一块鼓起来了，鼓包底下挂着一滴水。</p><p>她说，我今天在跟房东吵架。</p><p>她说，我今天没回你，是我在跟那个男的说话。</p><p>她说，他说&quot;我们这里所有楼都这样&quot;。</p><p>她说，我说那你把这块布给我。</p><p>她说，他说要申请。</p><p>她说，我说申请多久。</p><p>她说，他说两周。</p><p>她说，我说那两周一滴水会把我本子滴坏。</p><p>她说，他说那你把本子挪开。</p><p>她说，我当时站在那个走廊上，我一句话说不出来。</p><p>她说，因为我那个人生里所有的东西都是要挪开的。</p><p>她说，我的床要挪，我的桌子要挪，我的垫子要挪。</p><p>她说，我今天看到你那句&quot;你那边下雪吗&quot;，我拿这个跟我的漏水一比，我忽然觉得我这边的事特别可笑。</p><p>我说，你那边的事不可笑。</p><p>她说，我知道。</p><p>她说，我那天下午五点十六看到那三条的时候，我心里第一反应是高兴。</p><p>她说，第二反应是&quot;我今天回不了你&quot;。</p><p>她说，第三反应是我开始算我今天回他哪一句。</p><p>她说，我发现我在我们两个身上也在算这个。</p><p>她说，我不喜欢我这样。</p><p>我说，你已经告诉我了。</p><p>她说，对。</p><p>她说，我今天告诉你，不是为了让你谅解我。</p><p>她说，是为了让你别再往第四条发。</p><p>我说，好。</p><p>她说，你又&quot;好&quot;。</p><p>她说，你这个&quot;好&quot;是真的。</p><p>我说，我这次没憋。</p><p>她说，我知道。</p><p>她说，你要是憋了你今天会讲两句长的。</p><p>那年十二月，我们的记录里第一次出现了停在第三条的位置。</p><p>那天夜里我在那本被退回的箱子上贴了一张小条。</p><p>我写的是：三句。</p><p>我贴在那个箱子侧面。</p><p>不是给自己看的。</p><p>是我知道，有一天我搬这个箱子，谁搬，他都会看见这两个字。</p><p>我希望有一个人问一句这是什么意思。</p><p>我这辈子没有跟任何人讲过这个箱子里是什么。</p><p>那个冬天我们停了十九次在第三条。</p><p>我数过。</p><p>十九次里，她有十一次在第二天回来。</p><p>剩下那八次，她隔了一天才回。</p><p>那八次里她回的第一句都不是解释。</p><p>她回的是今天吃了什么。</p><p>我知道那一句是什么意思。</p><p>她是在告诉我：她那天确实不行了，但是她在第二天第一个想讲的还是吃饭。</p><p>那比对不起有用。</p>',143)])])}const l=t(a,[["render",_]]);export{d as __pageData,l as default};
